// One-time copy of all portfolio data from Supabase into Neon.
// Needs SUPABASE_URL, SUPABASE_SERVICE_ROLE_KEY and DATABASE_URL in server/.env,
// and the Supabase project must be awake (restore it from the dashboard if paused).
// Usage: npm run db:setup && npm run db:migrate
import sql from "../db/index.js";

const { SUPABASE_URL, SUPABASE_SERVICE_ROLE_KEY } = process.env;
if (!SUPABASE_URL || !SUPABASE_SERVICE_ROLE_KEY) {
  console.error("Set SUPABASE_URL and SUPABASE_SERVICE_ROLE_KEY in server/.env to migrate.");
  process.exit(1);
}

// Columns copied per table. Ids are regenerated by Neon — nothing references them.
const TABLES = {
  admin_users:        ["username", "password_hash"],
  projects:           ["title", "description", "tech", "github", "live", "featured", "image_url", "visible", "order_index"],
  skills:             ["name", "category", "level", "details", "visible", "order_index"],
  experience:         ["role", "company", "duration", "type", "points", "visible", "order_index"],
};

async function fetchTable(table) {
  const res = await fetch(`${SUPABASE_URL}/rest/v1/${table}?select=*`, {
    headers: { apikey: SUPABASE_SERVICE_ROLE_KEY, Authorization: `Bearer ${SUPABASE_SERVICE_ROLE_KEY}` },
  });
  if (!res.ok) throw new Error(`Supabase ${table}: ${res.status} ${await res.text()}`);
  return res.json();
}

for (const [table, columns] of Object.entries(TABLES)) {
  const [{ count }] = await sql.query(`SELECT count(*)::int AS count FROM ${table}`);
  if (count > 0) {
    console.log(`${table}: Neon already has ${count} rows — skipped`);
    continue;
  }

  const rows = await fetchTable(table);
  const placeholders = columns.map((_, i) => `$${i + 1}`).join(", ");
  for (const row of rows) {
    await sql.query(
      `INSERT INTO ${table} (${columns.join(", ")}) VALUES (${placeholders})`,
      columns.map((c) => row[c] ?? null),
    );
  }
  console.log(`${table}: copied ${rows.length} rows`);
}

const [views] = await fetchTable("page_views");
if (views) {
  await sql`UPDATE page_views SET count = GREATEST(count, ${views.count}) WHERE id = 1`;
  console.log(`page_views: count set to ${views.count}`);
}

console.log("Migration complete.");
